// Invoke the target function with no arguments, as required by the API
const char *ret = advobf_demo();

// Prepare an output handle of type const char ** so the fuzzer runtime can persist it
const char **str_ptr = (const char **)malloc(sizeof(const char *));
if (!str_ptr) { FUZZ_BAIL(); }
*str_ptr = ret; // Store the returned pointer (may be NULL) without taking ownership

// The returned pointer is documented as read-only and potentially NULL; never modify or free it.
// If non-NULL, conservatively probe its length up to a cap to avoid overruns.
int is_null = (ret == nullptr);
int observed_len = -1; // -1 indicates unknown because ret is NULL
if (!is_null) {
    // Bounded scan for NUL terminator to avoid unbounded reads if contract is violated
    const int MAX_PROBE = 1024;
    observed_len = 0;
    for (int i = 0; i < MAX_PROBE; ++i) {
        if (ret[i] == '\0') { break; }
        observed_len++;
    }
}

// Attach attributes describing the state for downstream stubs
FUZZ_SET_ATTR_INT(str_ptr, "is_null", is_null);
FUZZ_SET_ATTR_INT(str_ptr, "len_probe", observed_len);
// Note: Do not attempt to free *str_ptr; ownership and lifetime are unspecified by the API.

// Validation summary: we honored the zero-arg call, treated output as read-only, handled NULL safely,
// and persisted the pointer via a const char ** handle with metadata.
